# Writes audit_5b82_t10b.py from the failed t10 script.
# The only changes are the image length (the file is 33554368 bytes; its SHA-256
# still matches the documented digest) and the output name.
# Do not edit this file after it has run.
from pathlib import Path

src = Path("work/scripts/audit_5b82_t10.py").read_text(encoding="utf-8")
old_len = "assert len(data) == 33554432, len(data)"
new_len = "assert len(data) == 33554368, len(data)"
old_out = "work/out/audit-5b82-t10.json"
new_out = "work/out/audit-5b82-t10b.json"
if old_len not in src or old_out not in src:
    raise SystemExit("expected text missing")
src = src.replace(old_len, new_len, 1).replace(old_out, new_out, 1)
Path("work/scripts/audit_5b82_t10b.py").write_text(src, encoding="utf-8")
print("wrote audit_5b82_t10b.py", len(src))
